"""Reproducible editorial ledger; this records the author's review, not an independent language test."""
import json,re,hashlib
from pathlib import Path
p=Path(__file__).resolve().parent;root=p.parent
html=(root/'release135/JLPT_N1_ukrainian_reading_v135.html').read_text();base=(root/'JLPT_N1_ukrainian_reading_v134.html').read_text()
new=json.loads((p/'new-readings.json').read_text());coverage=json.loads((p/'coverage.json').read_text())
def get(s,n):return json.JSONDecoder().raw_decode(s[re.search(r'const '+n+r'\s*=\s*',s).end():])[0]
old=get(base,'readingBank');built=get(html,'readingBank')
oldg={int(n['id']) for group in old.values() for x in group for n in x.get('contextNotes',[]) if n['kind']=='g'}
newg={n['itemId'] for n in coverage if n['kind']=='g'}
assert not oldg&newg and len(newg)==18
# Reasons correspond to the three incorrect authored choices, before presentation rotation.
reasons={
'm135-01':[['Не про просторове розташування.','Роль замісного запитувача не призначали.','Немає правила черговості запитань.'],['Оповідач сам не розумів; мотив не лише допомога іншим.','Помилки схеми не встановлював.','Не заявляв про відмову бути наставником.']],
'm135-02':[['Перший аркуш був успішний, несправність ще не знайдена.','Проба далі тривала з іншим папером.','Умови записують окремо, не зливають.'],['Причина майбутнього застрягання не визначена.','Запис не запобігає сам собою несправностям.','Для іншого паперу зробили інший запис.']],
'm135-03':[['Робочу назву можна перевірити перед друком.','Верстання дозволене з тимчасовою назвою.','Фраза описує запасну дію, не минулий мотив невдоволення.'],['Подали як «Без назви», іншої назви не вимагали.','Зміни решти назв не зазначені.','Фотографію не вилучили.']],
'm135-04':[['Старіння чи непридатність експоната не названі.','Знав, яку модель везти; бракувало даних для перенесення.','Вагу не передали; помилкової дати немає.'],['Не послідовність полегшення.','Кілограми означають вагу, не число коробок.','Конструкція вагу підкреслює, а не заперечує.']],
'm135-05':[['Ця похвала вже була в першій версії.','Мета не перелічити всі вади заводу.','Такого способу скасувати перевірки не пропонували.'],['Перевагу власної системи не доведено.','Однакове обладнання не гарантує однакового результату.','Ще не вирішили збільшити перевірки: спершу з’ясують, які пропускають.']],
'm135-06':[['Невідома навіть адреса, не тільки ім’я.','Адресу не пропустили через свідомий пріоритет.','Знання прізвища не підтверджує адресу чи особу.'],['Прізвисько корисне для спогаду, не гарантія точного пошуку адреси.','Встановлені прізвища зберігають поруч, не відкидають.','Багато людей ще не знайдені.']],
'm135-07':[['Відповідь друга на фото була пізніше й не відмовою від мистецтва.','Правила ресторану про двох відвідувачів не згадані.','Зміни поїзда не описано.'],['Автор прямо не оголошує одиночну подорож завжди кращою.','Він змінив план відповідно до обставин.','Можна змінити день, не відкидати спільного задуму.']],
'm135-08':[['У першій репліці немає категоричного висновку про зал.','Ніхто не просив знищити запис.','Йдеться про чутність, не незгоду зі змістом.'],['У кімнаті слова розуміли; проблема умов чутності, не змісту виступу.','Повний перезапис ще не вирішили.','Перевірка не мала нав’язати повторну згоду.']],
'm135-09':[['Назва не змінює екран; питання про критерій рішення.','Запитання з’явилися під час реального виконання.','Новачок працює з екраном, не лише скороченнями.'],['Власної зрозумілості недостатньо для іншого читача.','Інструкцію успішно доопрацьовують.','Обсяг залежить від знань і труднощів читача.']],
'm135-10':[['Повернути треба книжки, не пакунок дядька.','Після бібліотеки дядько чекав із чаєм і фото.','Не вимагав пріоритету свого візиту.'],['Тривалість узгоджують, не завжди обмежують.','Передоручення повернення книжок не описано.','Не обіцяють довгого візиту без погодження.']],
'm135-11':[['にして тут не позначає попередній етап.','Автор уже був першим читачем власної роботи.','Ролі поєднуються, а не виключаються.'],['Один друг не представляє всіх; сцену не вилучено.','Не брак знань про задум, а надлишок недоступних читачеві відомостей.','Змінив порядок малюнків, не просто збільшив пояснення.']],
'm135-12':[['Текст прямо заперечує відмову від пошуку.','Ще шукають і перевіряють, наказу немає.','Працівник бере участь у пошуку.'],['Практична проба показала недоліки плану.','Мокра підлога й перекритий вихід — окремі умови.','Від ремонту не відмовилися.']],
'l135-01':[['Результат повторного відправлення не підтверджений.','Недосвідченість не скасовує відповідальності.','Висновок ґрунтується на змісті продовження, не лише ввічливості.'],['Помилка прямо визнана в листі.','Об’єкт вибачення прямо названо.','Лист покладає оплату на крамницю, не покупця.'],['Один лист не підтверджує ставлення всіх крамниць.','Неперевірене виконання не заперечує наявної обіцянки.','Невідоме залишено в поясненні й воно спричинило новий пошук.']],
'l135-02':[['Станцію не збудували; не йдеться про гарантований вплив на всіх.','Однаковий тип ліній міг би спотворити стадію плану.','Зміна місця без мотиву не встановлює всіх причин.'],['Переїзди є; розрізняють докази причини.','Очікування можуть впливати до будівництва.','Пояснення зв’язків дозволене з указаними межами доказу.'],['Порівняння не доводить побудови планової лінії.','Другу карту з планом не прибрали.','Рівного чи більшого обсягу для всіх планів не вимагають.']],
'l135-03':[['Бруд сам собою не мета; після запису коробку пересунули.','Про стирання дати всередині не сказано.','Вміст перевірили після фотографування.'],['Час заміни меблів тільки пропонують дослідити.','Дослідну цінність не відкинуто.','Зовнішня фотографія не підтверджує вмісту.'],['Неперевірене позначають, а не змішують.','Початковий стан записують до втручання.','Деталізацію добирають, не витрачають однаковий час на все.']],
'l135-04':[['Дата й час потрібні; бракувало визначення події.','Сам початок введення не достатній.','Паперовий спосіб зберігають.'],['Лист-підтвердження не критерій.','Рекомендований запас часу не змінює формального строку.','Пізніших паперових документів для онлайн не вимагали.'],['Новий спосіб вимагає пояснення, навіть зі старою формулою.','Контакт потрібний попри деталізацію.','Розбіжні відповіді використано для поліпшення оголошення.']],
'l135-05':[['Знищення початкового запису не пропонували.','Запитання було до розданої невиправленої таблиці.','Ключ — інше запитання наступних зборів.'],['Сумніву в реальному віці не було.','Автор не збирався пояснювати дітям.','Це пізніше переосмислення, не ставлення у першій репліці.'],['Більше запитань не означало передоручення всіх рішень.','Помилку й домовленість саме розмежували.','Досвідчений теж перепитав.']],
'l135-06':[['Автор не зміг стримати подиву.','Подив виразно названий.','Розчарування на місці захоплення немає.'],['Такого судження організатор не висував.','Відгук писати можна, автор його переробив.','Описано можливість уточнювати гіпотези, не остаточне спростування цього призначення.'],['Застереження саме не доводить правильності.','Невідоме стимулює перевірку, а не скасовує її.','Автор залишається неназваним.']]
}
rows=[];passages=[]
for x in new:
 target=next(y for y in built[x['level']] if y.get('id')==x['id'])
 assert len(reasons[x['id']])==len(x['questions'])
 passages.append(dict(id=x['id'],title=x['title'],jaCharacters=len(x['ja']),paragraphs=x['ja'].count('\n\n')+1,reviewScope='author review: Japanese context, Ukrainian translation, grammar attachment/register, question evidence and distractors',independentReview=False))
 for i,(q,bq,rs) in enumerate(zip(x['questions'],target['questions'],reasons[x['id']])):
  assert len(rs)==3
  rows.append(dict(readingId=x['id'],questionIndex=i,prompt=q['prompt'],correctAnswer=q['choices'][0],displayAnswerIndex=bq['answer'],evidence=q['evidence'],reason=q['explain'],rejectedOptions=[dict(text=c,reason=r) for c,r in zip(q['choices'][1:],rs)]))
direct=[('m135-01',0,12),('m135-03',0,18),('m135-04',1,107),('m135-06',0,14),('m135-07',1,120),('m135-08',0,88),('m135-09',1,72),('m135-11',0,96),('m135-12',0,92),('l135-02',0,10),('l135-05',1,33),('l135-06',0,52)]
links=[]
for rid,qi,gid in direct:
 x=next(x for x in new if x['id']==rid);assert gid in {n[0] for n in x['grammar']}
 links.append(dict(readingId=rid,questionIndex=qi,kind='g',itemId=gid,coverageType='direct_context_question',prompt=x['questions'][qi]['prompt']))
report=dict(htmlSha256=hashlib.sha256(html.encode()).hexdigest(),reviewType='author_editorial_review',independentReview=False,officialJLPTCalibration=False,baselineAnnotatedGrammarIds=len(oldg),newPreviouslyUnannotatedGrammarIds=sorted(newg),passages=passages,questions=rows)
(p/'editorial-review.json').write_text(json.dumps(report,ensure_ascii=False,indent=2))
(p/'direct-question-links.json').write_text(json.dumps(links,ensure_ascii=False,indent=2))
print('Editorial ledger:',len(passages),'texts,',len(rows),'questions,',len(links),'direct grammar questions')
